/** Every registry entry, for preloading. */
export function allBuildingAssets() {
  return Object.values(BUILDING_ASSETS);
}

/** Accepts "type_aspect" or the shorter "type:aspect" form. */
export function resolveAssetId(id) {
  if (!id) return null;
  if (BUILDING_ASSETS[id]) return id;
  const alt = String(id).replace(":", "_");
  return BUILDING_ASSETS[alt] ? alt : null;
}

/**
 * Resolve an asset id to a loaded image, or null when it is still loading
 * or unknown. Callers must fall back to the procedural renderer then, so
 * missing art degrades to the plain building instead of a hole.
 */
export function getBuildingImage(id) {
  const key = resolveAssetId(id);
  if (!key) return null;
  const a = BUILDING_ASSETS[key];
  if (!a || !a.img || !a.img.complete || !a.img.naturalWidth) return null;
  return a.img;
}

/** True when the id exists in the registry (used to validate map data). */
export function isBuildingAsset(id) {
  return resolveAssetId(id) !== null;
}
